import { pet } from './utils/pets';
import { FLAG_US, FLAG_MX, FLAG_VN, FLAG_CN, FLAG_FR, FLAG_DE, FLAG_BR, FLAG_IT, FLAG_NL, FLAG_PL, FLAG_TR, FLAG_ID, FLAG_PH, FLAG_SE } from './flags';
/**
 * Player-facing strings (many languages) and the language preference.
 *
 * English values are exactly the strings the game always showed, so English output is unchanged.
 * Kept in English on purpose (not in this table): the game title, mode names, boss names,
 * JOHN S E E DVOR SNACK / ADAM SLURRY, THE DUCHESS OF PASADENA and the Venmo handle.
 */
export type Lang = 'en' | 'es' | 'vi' | 'zh' | 'fr' | 'de' | 'pt' | 'it' | 'nl' | 'pl' | 'tr' | 'id' | 'fil' | 'sv';

/**
 * LANGUAGE dropdown order (MODES screen); each name is written in its own language, shown after
 * its flag (inline SVG from flags.ts). A new language: add it here (with its flag) and to STRINGS.
 */
export const LANGS: { id: Lang; name: string; html: string; flag: string }[] = [
  { id: 'en', name: 'English', html: 'en', flag: FLAG_US },
  { id: 'es', name: 'Español', html: 'es', flag: FLAG_MX },
  { id: 'vi', name: 'Tiếng Việt', html: 'vi', flag: FLAG_VN },
  { id: 'zh', name: '简体中文', html: 'zh-Hans', flag: FLAG_CN },
  { id: 'fr', name: 'Français', html: 'fr', flag: FLAG_FR },
  { id: 'de', name: 'Deutsch', html: 'de', flag: FLAG_DE },
  { id: 'pt', name: 'Português', html: 'pt', flag: FLAG_BR },
  { id: 'it', name: 'Italiano', html: 'it', flag: FLAG_IT },
  { id: 'nl', name: 'Nederlands', html: 'nl', flag: FLAG_NL },
  { id: 'pl', name: 'Polski', html: 'pl', flag: FLAG_PL },
  { id: 'tr', name: 'Türkçe', html: 'tr', flag: FLAG_TR },
  { id: 'id', name: 'Bahasa Indonesia', html: 'id', flag: FLAG_ID },
  { id: 'fil', name: 'Filipino', html: 'fil', flag: FLAG_PH },
  { id: 'sv', name: 'Svenska', html: 'sv', flag: FLAG_SE },
];

const KEY = 'fsb_lang';

export function isLang(v: unknown): v is Lang {
  return LANGS.some((l) => l.id === v);
}

/** Saved choice, else the browser language (es / vi / zh, any region), else English. */
export function detectLang(nav: string): Lang {
  const n = nav.toLowerCase();
  // Longer / special prefixes first.
  if (n.startsWith('zh')) return 'zh';
  if (n.startsWith('fil') || n.startsWith('tl')) return 'fil';
  if (n.startsWith('pt')) return 'pt';
  if (n.startsWith('es')) return 'es';
  if (n.startsWith('vi')) return 'vi';
  if (n.startsWith('fr')) return 'fr';
  if (n.startsWith('de')) return 'de';
  if (n.startsWith('it')) return 'it';
  if (n.startsWith('nl')) return 'nl';
  if (n.startsWith('pl')) return 'pl';
  if (n.startsWith('tr')) return 'tr';
  if (n.startsWith('id') || n.startsWith('in')) return 'id';
  if (n.startsWith('sv')) return 'sv';
  return 'en';
}

function detect(): Lang {
  try {
    const saved = localStorage.getItem(KEY);
    if (isLang(saved)) return saved;
  } catch {
    /* storage blocked */
  }
  try {
    return detectLang(typeof navigator !== 'undefined' ? navigator.language || '' : '');
  } catch {
    return 'en';
  }
}

let current: Lang = detect();
const listeners: ((l: Lang) => void)[] = [];

export function lang(): Lang {
  return current;
}

/** Any language but English (text can run longer, or need other fonts / wrapping). */
export function nonEnglish(): boolean {
  return current !== 'en';
}

export function setLang(l: Lang): void {
  try {
    localStorage.setItem(KEY, l);
  } catch {
    /* storage blocked */
  }
  if (l === current) return;
  current = l;
  for (const cb of listeners) cb(l);
}

export function onLang(cb: (l: Lang) => void): void {
  listeners.push(cb);
}

/** Whole number with thousands separators: en / zh 1,048,576; es / vi 1.048.576 (never 'e' notation). */
export function fmtNum(n: number): string {
  const s = Math.floor(n).toLocaleString('en-US'); // never scientific notation
  // Dot thousands: es, vi, de, nl, it, pt, id, tr
  if (
    current === 'es' ||
    current === 'vi' ||
    current === 'de' ||
    current === 'nl' ||
    current === 'it' ||
    current === 'pt' ||
    current === 'id' ||
    current === 'tr'
  ) {
    return s.replace(/,/g, '.');
  }
  // Narrow no-break space (U+202F): fr
  if (current === 'fr') return s.replace(/,/g, '\u202f');  // narrow no-break space
  // Space thousands: pl, sv
  if (current === 'pl' || current === 'sv') return s.replace(/,/g, ' ');
  // Comma thousands (en, zh, fil): leave as-is
  return s;
}

